const fs = require('fs');
const zlib = require('zlib');

const src = '/workspace/testbed/docs/travel_summary.docx';
const buf = fs.readFileSync(src);

// Parse ZIP entries (local file headers)
let offset = 0;
const entries = [];
while (offset < buf.length - 4) {
  const sig = buf.readUInt32LE(offset);
  if (sig !== 0x04034b50) break;
  const compMethod = buf.readUInt16LE(offset + 8);
  const compSize = buf.readUInt32LE(offset + 18);
  const uncompSize = buf.readUInt32LE(offset + 22);
  const fnameLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const fname = buf.toString('utf8', offset + 30, offset + 30 + fnameLen);
  const dataStart = offset + 30 + fnameLen + extraLen;
  const dataEnd = dataStart + compSize;
  entries.push({ fname, compMethod, compSize, uncompSize, dataStart, dataEnd, headerStart: offset });
  offset = dataEnd;
}

// Extract word/document.xml
const docEntry = entries.find(f => f.fname === 'word/document.xml');
let xml;
if (docEntry.compMethod === 0) {
  xml = buf.toString('utf8', docEntry.dataStart, docEntry.dataEnd);
} else {
  xml = zlib.inflateRawSync(buf.slice(docEntry.dataStart, docEntry.dataEnd)).toString('utf8');
}

// Add a new paragraph before the closing </w:body>
const note = 'Note: All Seattle-related travel records for Maya Chen have been reviewed and are up to date as of this summary.';
const newPara = '<w:p><w:r><w:t>' + note + '</w:t></w:r></w:p>';
xml = xml.replace('</w:body>', newPara + '</w:body>');

// Rebuild the zip: we'll use a simple approach — reconstruct with stored (no compression) entries
// to keep it simple and valid.

// Read all entries' data
const fileContents = {};
for (const e of entries) {
  if (e.compMethod === 0) {
    fileContents[e.fname] = buf.slice(e.dataStart, e.dataEnd);
  } else {
    fileContents[e.fname] = zlib.inflateRawSync(buf.slice(e.dataStart, e.dataEnd));
  }
}
// Replace document.xml with modified version
fileContents['word/document.xml'] = Buffer.from(xml, 'utf8');

// Build new ZIP
const parts = [];
const centralDir = [];
for (const e of entries) {
  const data = fileContents[e.fname];
  const fnBuf = Buffer.from(e.fname, 'utf8');
  const localOffset = parts.reduce((s, b) => s + b.length, 0);

  // Local file header (store, no compression)
  const lh = Buffer.alloc(30 + fnBuf.length);
  lh.writeUInt32LE(0x04034b50, 0);    // sig
  lh.writeUInt16LE(20, 4);            // version needed
  lh.writeUInt16LE(0, 6);             // flags
  lh.writeUInt16LE(0, 8);             // compression: stored
  lh.writeUInt16LE(0, 10);            // mod time
  lh.writeUInt16LE(0, 12);            // mod date
  // crc32
  const crc = crc32(data);
  lh.writeInt32LE(crc, 14);
  lh.writeUInt32LE(data.length, 18);  // compressed size
  lh.writeUInt32LE(data.length, 22);  // uncompressed size
  lh.writeUInt16LE(fnBuf.length, 26); // filename length
  lh.writeUInt16LE(0, 28);            // extra length
  fnBuf.copy(lh, 30);
  parts.push(lh, data);

  // Central directory entry
  const cd = Buffer.alloc(46 + fnBuf.length);
  cd.writeUInt32LE(0x02014b50, 0);
  cd.writeUInt16LE(20, 4);
  cd.writeUInt16LE(20, 6);
  cd.writeUInt16LE(0, 8);
  cd.writeUInt16LE(0, 10);
  cd.writeUInt16LE(0, 12);
  cd.writeUInt16LE(0, 14);
  cd.writeInt32LE(crc, 16);
  cd.writeUInt32LE(data.length, 20);
  cd.writeUInt32LE(data.length, 24);
  cd.writeUInt16LE(fnBuf.length, 28);
  cd.writeUInt16LE(0, 30);
  cd.writeUInt16LE(0, 32);
  cd.writeUInt16LE(0, 34);
  cd.writeUInt16LE(0, 36);
  cd.writeUInt32LE(0, 38);
  cd.writeUInt32LE(localOffset, 42);
  fnBuf.copy(cd, 46);
  centralDir.push(cd);
}

const cdOffset = parts.reduce((s, b) => s + b.length, 0);
const cdSize = centralDir.reduce((s, b) => s + b.length, 0);

// End of central directory
const eocd = Buffer.alloc(22);
eocd.writeUInt32LE(0x06054b50, 0);
eocd.writeUInt16LE(0, 4);
eocd.writeUInt16LE(0, 6);
eocd.writeUInt16LE(entries.length, 8);
eocd.writeUInt16LE(entries.length, 10);
eocd.writeUInt32LE(cdSize, 12);
eocd.writeUInt32LE(cdOffset, 16);
eocd.writeUInt16LE(0, 20);

const result = Buffer.concat([...parts, ...centralDir, eocd]);
fs.writeFileSync(src, result);
console.log('Document updated successfully.');

// CRC32 implementation
function crc32(buf) {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) {
    crc ^= buf[i];
    for (let j = 0; j < 8; j++) {
      crc = (crc >>> 1) ^ (crc & 1 ? 0xEDB88320 : 0);
    }
  }
  return (crc ^ 0xFFFFFFFF) | 0;
}
