const fs = require('fs');
const zlib = require('zlib');
const { PDFDocument, StandardFonts, rgb } = require('pdf-lib');

async function convert() {
  // 1. Extract text from docx
  const buf = fs.readFileSync('/workspace/testbed/docs/travel_summary.docx');
  let offset = 0;
  while (offset < buf.length - 4) {
    const sig = buf.readUInt32LE(offset);
    if (sig !== 0x04034b50) break;
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const fnameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const fname = buf.toString('utf8', offset + 30, offset + 30 + fnameLen);
    const dataStart = offset + 30 + fnameLen + extraLen;
    const dataEnd = dataStart + compSize;
    if (fname === 'word/document.xml') {
      const xml = compMethod === 0
        ? buf.toString('utf8', dataStart, dataEnd)
        : zlib.inflateRawSync(buf.slice(dataStart, dataEnd)).toString('utf8');

      // Parse paragraphs with style info
      const lines = [];
      const pRe = /<w:p[ >][\s\S]*?<\/w:p>/g;
      let pm;
      while ((pm = pRe.exec(xml)) !== null) {
        const pXml = pm[0];
        // Check for heading style
        const styleMatch = pXml.match(/<w:pStyle\s+w:val=\"([^\"]*)\"/);
        const style = styleMatch ? styleMatch[1] : 'Normal';
        // Check for bold
        const hasBold = /<w:b[\s\/]/.test(pXml);
        // Extract text
        const texts = [];
        const tRe = /<w:t[^>]*>([^<]*)<\/w:t>/g;
        let tm;
        while ((tm = tRe.exec(pXml)) !== null) texts.push(tm[1]);
        const text = texts.join('');
        if (text) lines.push({ text, style, hasBold });
      }

      // 2. Build PDF
      const pdfDoc = await PDFDocument.create();
      const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
      const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

      const pageWidth = 612;   // Letter
      const pageHeight = 792;
      const marginLeft = 50;
      const marginRight = 50;
      const marginTop = 50;
      const marginBottom = 50;
      const usableWidth = pageWidth - marginLeft - marginRight;

      let page = pdfDoc.addPage([pageWidth, pageHeight]);
      let y = pageHeight - marginTop;

      for (const line of lines) {
        let fontSize, font, lineSpacing, extraSpaceBefore;

        if (line.style === 'Heading1' || (line.hasBold && lines.indexOf(line) === 0)) {
          fontSize = 18; font = fontBold; lineSpacing = 28; extraSpaceBefore = 10;
        } else if (line.style === 'Heading2' || (line.hasBold && line.text.match(/^(Flights|Hotels|Car Rentals|Note)/))) {
          fontSize = 13; font = fontBold; lineSpacing = 22; extraSpaceBefore = 14;
        } else if (line.text.startsWith('Note:')) {
          fontSize = 10; font = fontBold; lineSpacing = 16; extraSpaceBefore = 14;
        } else {
          fontSize = 8; font = fontRegular; lineSpacing = 13; extraSpaceBefore = 0;
        }

        // Word-wrap
        const words = line.text.split(' ');
        const wrappedLines = [];
        let current = '';
        for (const word of words) {
          const test = current ? current + ' ' + word : word;
          const width = font.widthOfTextAtSize(test, fontSize);
          if (width > usableWidth && current) {
            wrappedLines.push(current);
            current = word;
          } else {
            current = test;
          }
        }
        if (current) wrappedLines.push(current);

        const totalHeight = extraSpaceBefore + wrappedLines.length * lineSpacing;
        if (y - totalHeight < marginBottom) {
          page = pdfDoc.addPage([pageWidth, pageHeight]);
          y = pageHeight - marginTop;
        }

        y -= extraSpaceBefore;
        for (const wl of wrappedLines) {
          y -= lineSpacing;
          page.drawText(wl, { x: marginLeft, y, size: fontSize, font, color: rgb(0, 0, 0) });
        }
      }

      const pdfBytes = await pdfDoc.save();
      const outPath = '/workspace/testbed/docs/travel_summary.pdf';
      fs.writeFileSync(outPath, pdfBytes);
      console.log('PDF created: ' + outPath);
      console.log('Size: ' + (pdfBytes.length / 1024).toFixed(1) + ' KB');
      console.log('Pages: ' + pdfDoc.getPageCount());
    }
    offset = dataEnd;
  }
}
convert().catch(e => { console.error(e); process.exit(1); });
"

