  let offset = 0;
  while (offset < buf.length - 4) {
    const sig = buf.readUInt32LE(offset);
    if (sig !== 0x04034b50) break;
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const fnameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const fname = buf.toString('utf8', offset + 30, offset + 30 + fnameLen);
    const dataStart = offset + 30 + fnameLen + extraLen;
    const dataEnd = dataStart + compSize;
    if (fname === 'word/document.xml') {
      const xml = compMethod === 0
        ? buf.toString('utf8', dataStart, dataEnd)
        : zlib.inflateRawSync(buf.slice(dataStart, dataEnd)).toString('utf8');

      const lines = [];
      const pRe = /<w:p[ >][\s\S]*?<\/w:p>/g;
      let pm;
      while ((pm = pRe.exec(xml)) !== null) {
        const pXml = pm[0];
        const styleMatch = pXml.match(/<w:pStyle\s+w:val=\"([^\"]*)\"/);
        const style = styleMatch ? styleMatch[1] : 'Normal';
        const hasBold = /<w:b[\s\/]/.test(pXml);
        const texts = [];
        const tRe = /<w:t[^>]*>([^<]*)<\/w:t>/g;
        let tm;
        while ((tm = tRe.exec(pXml)) !== null) texts.push(tm[1]);
        let text = texts.join('');
        // Replace non-WinAnsi characters
        text = text.replace(/\u2192/g, '->');  // → to ->
        text = text.replace(/[^\x00-\xFF]/g, '?');  // any other non-Latin1
        if (text) lines.push({ text, style, hasBold });
      }

      const pdfDoc = await PDFDocument.create();
      const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
      const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

      const pageWidth = 612;
      const pageHeight = 792;
      const mL = 50, mR = 50, mT = 50, mB = 50;
      const usableW = pageWidth - mL - mR;

      let page = pdfDoc.addPage([pageWidth, pageHeight]);
      let y = pageHeight - mT;

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        let fontSize, font, lineH, spaceBefore;

        const isTitle = (i === 0);
        const isSection = /^(Flights|Hotels|Car Rentals)$/.test(line.text.trim());
        const isNote = line.text.startsWith('Note:');

        if (isTitle) {
          fontSize = 18; font = fontBold; lineH = 26; spaceBefore = 0;
        } else if (isSection) {
          fontSize = 13; font = fontBold; lineH = 20; spaceBefore = 16;
        } else if (isNote) {
          fontSize = 10; font = fontBold; lineH = 16; spaceBefore = 16;
        } else {
          fontSize = 7.5; font = fontRegular; lineH = 12; spaceBefore = 0;
        }

        // Word-wrap
        const words = line.text.split(' ');
        const wrapped = [];
        let cur = '';
        for (const w of words) {
          const test = cur ? cur + ' ' + w : w;
          if (font.widthOfTextAtSize(test, fontSize) > usableW && cur) {
            wrapped.push(cur);
            cur = w;
          } else {
            cur = test;
          }
        }
        if (cur) wrapped.push(cur);

        const need = spaceBefore + wrapped.length * lineH;
        if (y - need < mB) {
          page = pdfDoc.addPage([pageWidth, pageHeight]);
          y = pageHeight - mT;
        }

        y -= spaceBefore;
        for (const wl of wrapped) {
          y -= lineH;
          page.drawText(wl, { x: mL, y, size: fontSize, font, color: rgb(0, 0, 0) });
        }
      }

      const pdfBytes = await pdfDoc.save();
      const outPath = '/workspace/testbed/docs/travel_summary.pdf';
